    private static bool ChainUpSetParent(nint self, nint newParent)
    {
        delegate* unmanaged[Cdecl]<nint, nint, int> slot =
            (delegate* unmanaged[Cdecl]<nint, nint, int>)ParentClassOf(self)->SetParent;

        if (slot is null)
        {
            return true;
        }

        return slot(self, newParent) != 0;
    }

    private static bool ChainUpSetStart(nint self, ulong start)
    {
        delegate* unmanaged[Cdecl]<nint, ulong, int> slot =
            (delegate* unmanaged[Cdecl]<nint, ulong, int>)ParentClassOf(self)->SetStart;

        if (slot is null)
        {
            throw new InvalidOperationException(
                "TimelineElement.set_start has no parent implementation; override OnSetStart.");
        }

        return slot(self, start) != 0;
    }

